export function getArticle(slug: string) {
  return articles.find((a) => a.slug === slug)
}

/** Every text of an article, in reading order (for reference numbering). */
export function articleTexts(a: Article): string[] {
  const t: string[] = [a.intro]
  for (const s of a.sections) for (const b of s.blocks) b.type === 'p' ? t.push(b.text) : t.push(...b.items)
  for (const f of a.faq) t.push(f.a)
  return t
}

/** The article's sources, numbered in order of first citation in the text, then any listed-only sources. */
export function articleSources(a: Article): Source[] {
  const ids = refsInOrder(articleTexts(a))
  for (const id of a.sources) if (!ids.includes(id) && SOURCES[id]) ids.push(id)
  return ids.map((id) => SOURCES[id])
}

